func TestPostCommit_EndedSession_SameBaseCommit_NoOverlap_AdvancesCarryForward(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}

	endedSessionID := "ended-no-overlap-advance"
	setupSessionWithCheckpoint(t, s, repo, dir, endedSessionID)

	endedState, err := s.loadSessionState(context.Background(), endedSessionID)
	require.NoError(t, err)
	endedAt := time.Now().Add(-5 * time.Minute)
	endedState.Phase = session.PhaseEnded
	endedState.EndedAt = &endedAt
	endedState.FilesTouched = []string{"test.txt"}
	endedState.CheckpointTranscriptStart = 0
	require.NoError(t, s.saveSessionState(context.Background(), endedState))

	originalFilesTouched := make([]string, len(endedState.FilesTouched))
	copy(originalFilesTouched, endedState.FilesTouched)

	unrelatedFile := filepath.Join(dir, "unrelated.txt")
	require.NoError(t, os.WriteFile(unrelatedFile, []byte("unrelated content"), 0o644))

	wt, err := repo.Worktree()
	require.NoError(t, err)
	_, err = wt.Add("unrelated.txt")
	require.NoError(t, err)

	cpID := id.MustCheckpointID("bc01bc02bc03")
	commitMsg := "unrelated commit\n\n" + trailers.CheckpointTrailerKey + ": " + cpID.String() + "\n"
	_, err = wt.Commit(commitMsg, &git.CommitOptions{
		Author: &object.Signature{
			Name:  "Test",
			Email: "test@test.com",
			When:  time.Now(),
		},
	})
	require.NoError(t, err)

	head, err := repo.Head()
	require.NoError(t, err)
	newHead := head.Hash().String()

	err = s.PostCommit(context.Background())
	require.NoError(t, err)

	endedState, err = s.loadSessionState(context.Background(), endedSessionID)
	require.NoError(t, err)
	assert.False(t, endedState.FullyCondensed,
		"ENDED session should remain uncondensed when the commit does not overlap")
	assert.Equal(t, originalFilesTouched, endedState.FilesTouched,
		"carry-forward files should be preserved for a later overlapping commit")
	assert.Equal(t, newHead, endedState.BaseCommit,
		"carry-forward session should advance to the new HEAD so future PostCommit discovery can still find it")
}

// TestPostCommit_StaleActiveSession_NotCondensed verifies that a stale ACTIVE
// session (agent killed without Stop hook) is NOT condensed into an unrelated
// commit from a different session.
//
// Root cause: when an agent is killed without the Stop hook firing, its session
// remains in ACTIVE phase permanently. The overlap check prevents stale sessions
// with unrelated files from being condensed. The isRecentInteraction guard
// ensures that genuinely-active sessions (recent LastInteractionTime) skip the
// overlap check, while stale sessions (old/nil LastInteractionTime) must pass it.
func TestPostCommit_StaleActiveSession_NotCondensed(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}

	// --- Create a stale ACTIVE session from an old commit ---
	// This simulates an agent that was killed without the Stop hook firing.

