		// shadow-tree lookup will stop discovering the session entirely.
		if !state.Phase.IsActive() && h.hasNew {
			logging.Debug(logCtx, "post-commit: advancing non-active carry-forward after non-overlap",
				slog.String("session_id", state.SessionID),
